    vowels = set('aeiou')
    v_cnt = sum(1 for c in s.lower() if c in vowels)
    c_cnt = sum(1 for c in s.lower() if c.isalpha() and c not in vowels)
    return (v_cnt, c_cnt)

def solve(n: int) -> int:
    ans = 1
    for i in range(1, n + 1):
